use vstd::prelude::*;

verus! {
    fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>>
        requires
            n >= 0,
            m >= 0,
        ensures
            result.len() == n,
            forall |i: usize| 0 <= i < n ==> result[i].len() == m,
            forall |i: usize, j: usize| 0 <= i < n && 0 <= j < m ==> 
                (j <= (i as i32) + k ==> result[i][j] == 1.0) &&
                (j > (i as i32) + k ==> result[i][j] == 0.0),
    {
        let mut result: Vec<Vec<f64>> = Vec::new();
        
        // Initialize the matrix with zeroes
        for _ in 0..n {
            result.push(vec![0.0; m]);
        }

        // Fill the matrix according to the lower-triangular band condition
        for i in 0..n
            invariant
                0 <= i <= n,
                forall |x: usize| 0 <= x < i ==> 
                    forall |y: usize| 0 <= y < m ==> 
                        (y <= (x as i32) + k ==> result[x][y] == 1.0) &&
                        (y > (x as i32) + k ==> result[x][y] == 0.0),
            decreases n - i,
        {
            for j in 0..m
                invariant
                    0 <= j <= m,
                    result[i].len() == m,
                decreases m - j,
            {
                if j <= (i as i32) + k {
                    result[i][j] = 1.0;
                } else {
                    result[i][j] = 0.0;
                }
            }
        }
        
        result
    }
}

